test('new English version cannot display old Vietnamese and unavailable translation quota keeps English usable',async({page})=>{const f=await translationSetup(page);await page.getByRole('button',{name:'Xem phạm vi và quota dịch',exact:true}).click();await page.getByRole('checkbox',{name:'Tôi đã đọc đoạn, xác nhận không có dữ liệu cá nhân và có quyền gửi nội dung này.',exact:true}).check();await page.getByRole('button',{name:'Dịch đoạn Anh → Việt',exact:true}).click();await expect(page.getByText('Đã có bản Việt đúng phiên bản',{exact:false})).toBeVisible();await page.getByLabel('Lời phụ đề tiếng Anh có thời gian',{exact:true}).fill('1\n00:00:01,000 --> 00:00:03,000\nDifferent English source version.');await page.getByRole('button',{name:'Lưu phiên bản phụ đề Anh',exact:true}).click();await page.getByLabel('Hiển thị phụ đề trong app',{exact:true}).selectOption('bilingual');await expect(page.getByText('Chưa có bản Việt cho phiên bản này.',{exact:false})).toBeVisible();await expect(page.getByText('VI: We are learning English.',{exact:false})).toHaveCount(0);f.controls.translationMode='quota-error';await page.getByLabel('Bắt đầu từ cue',{exact:true}).selectOption('1');await page.getByLabel('Kết thúc ở cue',{exact:true}).selectOption('3');await page.getByRole('button',{name:'Xem phạm vi và quota dịch',exact:true}).click();await expect(page.getByText('Chưa đủ hoặc chưa xác minh được quota',{exact:false})).toBeVisible();await expect(page.getByRole('button',{name:'Dịch đoạn Anh → Việt',exact:true})).toBeDisabled();expect(f.controls.translationCalls).toBe(1);});

test('saved Vietnamese is exposed only for the resolved gap and history, without another translation call',async({page})=>{const f=await translationSetup(page);await page.getByRole('button',{name:'Xem phạm vi và quota dịch',exact:true}).click();await page.getByRole('checkbox',{name:'Tôi đã đọc đoạn, xác nhận không có dữ liệu cá nhân và có quyền gửi nội dung này.',exact:true}).check();await page.getByRole('button',{name:'Dịch đoạn Anh → Việt',exact:true}).click();await expect(page.getByText('Đã có bản Việt đúng phiên bản',{exact:false})).toBeVisible();await page.getByRole('button',{name:'Luyện điền từ đoạn này',exact:true}).click();await page.getByRole('button',{name:'Bắt đầu điền từ đoạn đã chọn',exact:true}).click();await expect(page.getByText('VI: We are learning English.',{exact:false})).toHaveCount(0);await page.getByLabel('Từ còn thiếu',{exact:true}).fill('learning');await page.getByRole('button',{name:'Gửi từ còn thiếu',exact:true}).click();await expect(page.getByText('VI: We are learning English. · Gợi ý dịch máy DeepL (deepl.com)',{exact:true})).toBeVisible();await page.reload();await page.getByRole('button',{name:'Tiếp tục bài video',exact:true}).click();await expect(page.getByText('VI: We are learning English. · Gợi ý dịch máy DeepL (deepl.com)',{exact:true})).toBeVisible();await page.getByRole('link',{name:'Lịch sử luyện video',exact:true}).click();await page.getByRole('button',{name:'Xem kết quả lượt video',exact:true}).click();await expect(page.getByText('VI: We are learning English. · Gợi ý dịch máy DeepL (deepl.com)',{exact:true})).toBeVisible();expect(f.controls.translationCalls).toBe(1);});
test('reporting a current source error saves one technical result and future attempts omit that cue only',async({page})=>{const f=await setup(page);await startGap(page);f.controls.failAfterCommit=true;await page.getByRole('button',{name:'Báo timing lệch · bỏ qua lỗi',exact:true}).click();await expect(page.getByText('Chưa tải hoặc xác nhận được bài.',{exact:false})).toBeVisible();await page.getByRole('button',{name:'Thử lại',exact:true}).click();await expect(page.getByRole('heading',{name:/không tính sai/})).toBeVisible();expect([...f.practiceStates.values()][0]!.results.map(r=>r.outcome)).toEqual(['technical']);expect(f.sourceRows.size).toBe(1);await page.getByRole('link',{name:'Lịch sử luyện video',exact:true}).click();await page.getByRole('link',{name:'Chuẩn bị luyện lượt mới',exact:true}).click();await page.getByRole('button',{name:'Chuẩn bị lượt video mới',exact:true}).click();await page.getByRole('button',{name:'Bắt đầu điền từ đoạn đã chọn',exact:true}).click();await expect(page.getByText('1 câu thực có',{exact:false})).toBeVisible();await expect(page.getByText("We _____ go.",{exact:true})).toHaveCount(0);expect([...f.practiceStates.values()][0]!.results).toHaveLength(1);});
test('reported old translated result remains pinned when personal English subtitles are replaced',async({page})=>{const f=await translationSetup(page);await page.getByRole('button',{name:'Xem phạm vi và quota dịch',exact:true}).click();await page.getByRole('checkbox',{name:'Tôi đã đọc đoạn, xác nhận không có dữ liệu cá nhân và có quyền gửi nội dung này.',exact:true}).check();await page.getByRole('button',{name:'Dịch đoạn Anh → Việt',exact:true}).click();await expect(page.getByText('Đã có bản Việt đúng phiên bản',{exact:false})).toBeVisible();await page.getByRole('button',{name:'Luyện điền từ đoạn này',exact:true}).click();await page.getByRole('button',{name:'Bắt đầu điền từ đoạn đã chọn',exact:true}).click();await page.getByLabel('Từ còn thiếu',{exact:true}).fill('learning');await page.getByRole('button',{name:'Gửi từ còn thiếu',exact:true}).click();await expect(page.getByRole('heading',{name:'Đúng',exact:true})).toBeVisible();const original=structuredClone([...f.practiceStates.values()][0]!);await page.getByRole('button',{name:'Về Xem hiểu',exact:true}).click();await page.getByRole('button',{name:'Mở Xem hiểu và ghi Đã xem',exact:true}).click();f.controls.failAfterCommit=true;await page.getByRole('button',{name:'Báo lời sai cue 1',exact:true}).click();await expect(page.getByText('Chưa xác nhận được báo lỗi nguồn.',{exact:false})).toBeVisible();await page.getByRole('button',{name:'Thử lại',exact:true}).click();await expect(page.getByText('Câu nguồn đã báo lỗi · không dùng cho lượt luyện mới.',{exact:true})).toBeVisible();await page.getByLabel('Lời phụ đề tiếng Anh có thời gian',{exact:true}).fill('1\n00:00:01,000 --> 00:00:03,000\nWe now use corrected words.');await page.getByRole('button',{name:'Lưu phiên bản phụ đề Anh',exact:true}).click();await expect(page.getByRole('button',{name:/We now use corrected words/})).toBeVisible();await page.getByLabel('Hiển thị phụ đề trong app',{exact:true}).selectOption('bilingual');await expect(page.getByText('VI: We are learning English.',{exact:false})).toHaveCount(0);await page.getByRole('link',{name:'Lịch sử luyện video',exact:true}).click();await page.getByRole('button',{name:'Xem kết quả lượt video',exact:true}).click();await expect(page.getByText('We are learning English.',{exact:true})).toBeVisible();await expect(page.getByText('VI: We are learning English. · Gợi ý dịch máy DeepL (deepl.com)',{exact:true})).toBeVisible();await expect(page.getByText('Câu nguồn đã báo lỗi; giữ nguyên kết quả lần đầu.',{exact:true})).toBeVisible();expect([...f.practiceStates.values()][0]).toEqual(original);expect(f.controls.translationCalls).toBe(1);await page.screenshot({path:'.scratch/practice-game-video-20261101/evidence/19-pinned-history.png',fullPage:true});});
test('whole-video deletion cancels with Escape and restores focus; uncertain committed delete survives reload without resurrecting its draft',async({page})=>{const f=await setup(page);await startGap(page);await page.getByLabel('Từ còn thiếu',{exact:true}).fill('deleted private draft');const manage=page.url().split('/practice')[0]!+'/manage';await page.goto(manage);await page.getByRole('button',{name:'Xem phạm vi xóa',exact:true}).click();const dialog=page.getByRole('dialog',{name:'Xóa dữ liệu đã chọn?',exact:true});await expect(dialog).toBeVisible();await expect(dialog.getByRole('button',{name:'Hủy',exact:true})).toBeFocused();await page.keyboard.press('Shift+Tab');await expect(dialog.getByRole('button',{name:'Xác nhận xóa',exact:true})).toBeFocused();await page.keyboard.press('Tab');await expect(dialog.getByRole('button',{name:'Hủy',exact:true})).toBeFocused();await page.keyboard.press('Escape');await expect(dialog).toHaveCount(0);await expect(page.getByRole('button',{name:'Xem phạm vi xóa',exact:true})).toBeFocused();expect(f.practiceStates.size).toBe(1);await page.getByRole('button',{name:'Xem phạm vi xóa',exact:true}).click();await page.setViewportSize({width:390,height:844});expect(await page.evaluate(()=>document.documentElement.scrollWidth<=innerWidth)).toBe(true);await page.screenshot({path:'.scratch/practice-game-video-20261101/evidence/21-delete-confirm-mobile.png',fullPage:true});f.controls.failAfterCommit=true;await dialog.getByRole('button',{name:'Xác nhận xóa',exact:true}).click();await expect(dialog.getByText('Chưa xác nhận được lần xóa.',{exact:false})).toBeVisible();expect(f.rows).toHaveLength(0);expect(f.practiceStates.size).toBe(0);await page.reload();await expect(dialog).toBeVisible();await dialog.getByRole('button',{name:'Xác nhận xóa',exact:true}).click();await expect(page).toHaveURL(/\/videos$/);expect(f.deletions.receipts.size).toBe(1);expect(f.controls.payloads.at(-1)).toEqual(f.controls.payloads.at(-2));expect(await page.evaluate(()=>Object.keys(localStorage).filter(key=>key.startsWith('vocabflow.video.practice.v1:')||key.startsWith('vocabflow.video.delete.v1:')))).toEqual([]);});
test('partial translation/practice/segment/version deletion keeps source ownership and permits fresh writes at the new data revision',async({page})=>{const f=await translationSetup(page);await page.getByRole('button',{name:'Lưu đoạn khó',exact:true}).click();await expect(page.getByText('Đã lưu dữ liệu đoạn/vị trí riêng.',{exact:true})).toBeVisible();await page.getByRole('button',{name:'Xem phạm vi và quota dịch',exact:true}).click();await page.getByRole('checkbox',{name:'Tôi đã đọc đoạn, xác nhận không có dữ liệu cá nhân và có quyền gửi nội dung này.',exact:true}).check();await page.getByRole('button',{name:'Dịch đoạn Anh → Việt',exact:true}).click();await expect(page.getByText('Đã có bản Việt đúng phiên bản',{exact:false})).toBeVisible();await page.getByRole('button',{name:'Luyện điền từ đoạn này',exact:true}).click();await page.getByRole('button',{name:'Bắt đầu điền từ đoạn đã chọn',exact:true}).click();await page.getByLabel('Từ còn thiếu',{exact:true}).fill('private draft');const videoUrl=page.url().split('/practice')[0]!;await page.goto(videoUrl+'/manage');for(const kind of ['translation','practice','segment','version']){await page.getByLabel('Phạm vi dữ liệu',{exact:true}).selectOption(kind);const select=page.getByLabel('Mục sẽ xóa',{exact:true});await expect(select).toBeVisible();const id=await select.locator('option').nth(1).getAttribute('value');await select.selectOption(id!);await page.getByRole('button',{name:'Xem phạm vi xóa',exact:true}).click();await page.getByRole('dialog').getByRole('button',{name:'Xác nhận xóa',exact:true}).click();await expect(page.getByText('Đã xóa dữ liệu riêng trong phạm vi đã xác nhận.',{exact:true})).toBeVisible();}
  expect(f.rows).toHaveLength(1);expect(f.transcripts).toHaveLength(0);expect(f.practiceStates.size).toBe(0);expect(f.translationRuns.size).toBe(0);expect([...f.watches.values()][0]!.bookmarks).toEqual([]);await page.getByRole('link',{name:'Về video',exact:true}).click();await page.getByLabel('Lời phụ đề tiếng Anh có thời gian',{exact:true}).fill('1\n00:00:01,000 --> 00:00:03,000\nFresh source after deliberate deletion.');await page.getByRole('button',{name:'Lưu phiên bản phụ đề Anh',exact:true}).click();await expect(page.getByRole('button',{name:/Fresh source after deliberate deletion/})).toBeVisible();expect(f.rows[0]!.entry.dataRevision).toBe(4);expect(f.controls.nativeStarts).toBe(0);expect(f.controls.translationCalls).toBe(1);
});
test('deletion checkpoint failure dispatches nothing and can cancel, recover and confirm once',async({page})=>{const f=await setup(page);await add(page);await page.getByRole('link',{name:'Quản lý dữ liệu video',exact:true}).click();await page.getByRole('button',{name:'Xem phạm vi xóa',exact:true}).click();await page.evaluate(()=>{const original=Storage.prototype.setItem;(window as typeof window&{restoreDelete:()=>void}).restoreDelete=()=>{Storage.prototype.setItem=original;};Storage.prototype.setItem=function(key,value){if(key.startsWith('vocabflow.video.delete.v1:'))throw new DOMException('controlled storage failure');return original.call(this,key,value);};});await page.getByRole('button',{name:'Xác nhận xóa',exact:true}).click();await expect(page.getByText('Chưa xác nhận được lần xóa.',{exact:false})).toBeVisible();expect(f.deletions.receipts.size).toBe(0);await page.keyboard.press('Escape');await expect(page.getByRole('dialog')).toHaveCount(0);await page.evaluate(()=>{(window as typeof window&{restoreDelete:()=>void}).restoreDelete();});await page.getByRole('button',{name:'Xem phạm vi xóa',exact:true}).click();await page.getByRole('button',{name:'Xác nhận xóa',exact:true}).click();await expect(page).toHaveURL(/\/videos$/);expect(f.deletions.receipts.size).toBe(1);});
test('another tab deletion invalidates visible private source and a held old read; stale client writes cannot recreate it',async({page,context})=>{
  const f=await translationSetup(page),videoUrl=page.url(),video=f.rows[0]!.entry.id,version=f.transcripts[0]!.entry.versionId,second=await context.newPage();await mockAccount(second);await second.route('**/api/learners/*/video-library**',f.routeVideo);await second.goto(videoUrl+'/manage');
  let release!:()=>void,seen!:()=>void;const held=new Promise<void>(resolve=>{release=resolve;}),ready=new Promise<void>(resolve=>{seen=resolve;});let once=true;await page.route(`**/transcripts/${version}`,async route=>{if(!once)return route.fallback();once=false;const response=await f.app.request(route.request().url()),body=await response.text();seen();await held;await route.fulfill({status:response.status,headers:Object.fromEntries(response.headers.entries()),body});});
  await page.reload();await ready;await second.getByRole('button',{name:'Xem phạm vi xóa',exact:true}).click();await second.getByRole('button',{name:'Xác nhận xóa',exact:true}).click();await expect(second).toHaveURL(/\/videos$/);await expect(page.getByText('Video không có trong thư viện hồ sơ này hoặc chưa tải được.',{exact:false})).toBeVisible();release();await expect(page.getByRole('button',{name:/We are learning English/})).toHaveCount(0);const status=await page.evaluate(async({learner,video})=>(await fetch(`/api/learners/${learner}/video-library/${video}/transcripts`,{method:'POST',headers:{'Content-Type':'application/json','X-Video-Revision':'0'},body:JSON.stringify({versionId:crypto.randomUUID(),format:'srt',language:'en',text:'1\n00:00:01,000 --> 00:00:03,000\nLate stale private source.'})})).status,{learner:profile().id,video});expect(status).toBe(404);expect(f.transcripts).toHaveLength(0);expect(f.rows).toHaveLength(0);expect(f.controls.nativeStarts).toBe(0);await second.close();
});
test('blocked original player keeps saved bilingual text readable without automatic extraction or translation',async({page})=>{const f=await translationSetup(page);await page.getByRole('button',{name:'Xem phạm vi và quota dịch',exact:true}).click();await page.getByRole('checkbox',{name:'Tôi đã đọc đoạn, xác nhận không có dữ liệu cá nhân và có quyền gửi nội dung này.',exact:true}).check();await page.getByRole('button',{name:'Dịch đoạn Anh → Việt',exact:true}).click();await expect(page.getByText('Đã có bản Việt đúng phiên bản',{exact:false})).toBeVisible();await page.getByLabel('Hiển thị phụ đề trong app',{exact:true}).selectOption('bilingual');await page.evaluate(()=>{(window as typeof window&{__videoIO:{emitError:(code:number)=>void}}).__videoIO.emitError(101);});await expect(page.getByText('Chủ video không cho phát nhúng. Bạn có thể mở nguồn YouTube.',{exact:true})).toBeVisible();await expect(page.getByRole('button',{name:/We are learning English/})).toBeVisible();await expect(page.getByText('VI: We are learning English. · Gợi ý dịch máy DeepL (deepl.com)',{exact:true})).toBeVisible();expect(f.controls.nativeStarts).toBe(0);expect(f.controls.translationCalls).toBe(1);await page.setViewportSize({width:390,height:844});await page.screenshot({path:'.scratch/practice-game-video-20261101/evidence/21-blocked-source-readable.png',fullPage:true});});
test('corrupt deletion checkpoint requires explicit discard before starting a new scope',async({page})=>{const f=await setup(page);await add(page);const key=`vocabflow.video.delete.v1:account-a:${profile().id}:${f.rows[0]!.entry.id}`;await page.evaluate(key=>localStorage.setItem(key,'{corrupt'),key);await page.getByRole('link',{name:'Quản lý dữ liệu video',exact:true}).click();await expect(page.getByText('Bản nháp xóa trên thiết bị chưa đọc được.',{exact:false})).toBeVisible();await expect(page.getByRole('button',{name:'Xem phạm vi xóa',exact:true})).toBeDisabled();expect(f.deletions.receipts.size).toBe(0);await page.getByRole('button',{name:'Bỏ bản nháp xóa trên thiết bị',exact:true}).click();await page.getByRole('button',{name:'Xem phạm vi xóa',exact:true}).click();await expect(page.getByRole('dialog')).toBeVisible();await page.keyboard.press('Escape');expect(f.rows).toHaveLength(1);expect(await page.evaluate(key=>localStorage.getItem(key),key)).toBeNull();});
test('stale confirmation after another tab deletion can reload its scope instead of being trapped in endless retry',async({page,context})=>{const f=await translationSetup(page),videoUrl=page.url(),version=f.transcripts[0]!.entry.versionId;await page.goto(videoUrl+'/manage');await page.getByRole('button',{name:'Xem phạm vi xóa',exact:true}).click();const second=await context.newPage();await mockAccount(second);await second.route('**/api/learners/*/video-library**',f.routeVideo);await second.goto(videoUrl+'/manage?kind=version');await second.getByLabel('Mục sẽ xóa',{exact:true}).selectOption(version);await second.getByRole('button',{name:'Xem phạm vi xóa',exact:true}).click();await second.getByRole('button',{name:'Xác nhận xóa',exact:true}).click();await expect(second.getByText('Đã xóa dữ liệu riêng trong phạm vi đã xác nhận.',{exact:true})).toBeVisible();await page.getByRole('button',{name:'Xác nhận xóa',exact:true}).click();await expect(page.getByRole('dialog')).toHaveCount(0);await expect(page.getByText('Dữ liệu hoặc quyền truy cập đã thay đổi.',{exact:false})).toBeVisible();expect(f.deletions.receipts.size).toBe(1);expect(f.rows).toHaveLength(1);await page.getByRole('button',{name:'Xem phạm vi xóa',exact:true}).click();await expect(page.getByRole('dialog')).toBeVisible();await page.keyboard.press('Escape');await second.close();});
